`default_nettype none
module mmio_decoder(input wire clk,input wire rst,input wire valid,input wire we,input wire [31:0] addr,input wire [31:0] wdata,input wire [15:0] sw,input wire [4:0] btn,input wire [7:0] capture_in,input wire retire,input wire stall,input wire [1:0] fwd_ex,fwd_wb,input wire flush,branch,branch_taken,crc,output wire [31:0] rdata,output wire [15:0] led,output wire [31:0] test_result,output wire uart_tx,output wire pwm_out,output wire [7:0] capture_sample,output wire capture_armed,capture_triggered,capture_done);
 wire gpio_sel=addr[31:12]==20'h40000,uart_sel=addr[31:12]==20'h40001,timer_sel=addr[31:12]==20'h40002,pwm_sel=addr[31:12]==20'h40003,cap_sel=addr[31:12]==20'h40004,win_sel=addr[31:12]==20'h40005,perf_sel=addr[31:12]==20'h40006; wire [31:0] gdata,tdata,pdata,cdata,perfdata; wire uart_ready; wire uart_start=valid&&we&&uart_sel&&addr[3:0]==0&&uart_ready; wire clear=valid&&we&&perf_sel&&addr[5:2]==4'h9;
 gpio_mmio gpio(clk,rst,valid&&we&&gpio_sel,addr[3:0],wdata,sw,btn,led,test_result,gdata); uart_tx uart(clk,rst,uart_start,wdata[7:0],uart_ready,uart_tx); timer_mmio timer(clk,rst,addr[2:0],tdata); pwm_mmio pwm(clk,rst,valid&&we&&pwm_sel,addr[3:0],wdata,pwm_out); logic_capture cap(clk,rst,capture_in,valid&&we&&cap_sel,addr[4:0],wdata,win_sel,addr[13:2],cdata,capture_sample,capture_armed,capture_triggered,capture_done); perf_counter perf(clk,rst,retire,stall,fwd_ex,fwd_wb,flush,branch,branch_taken,crc,clear,addr[6:2],perfdata);
 assign rdata=gpio_sel?gdata:timer_sel?tdata:pwm_sel?pdata:(cap_sel||win_sel)?cdata:perf_sel?perfdata:32'd0;
endmodule
`default_nettype wire
